"use client";

import { CartesianGrid, Line, LineChart, XAxis, YAxis } from "recharts";
import { cn } from "../../../lib/utils";
import { Card, CardContent, CardHeader, CardTitle } from "../../ui/card/card";
import {
  type ChartConfig,
  ChartContainer,
  ChartTooltip,
  ChartTooltipContent,
} from "../../ui/chart/chart";

export type TrafficDataPoint = {
  /** ISO date (YYYY-MM-DD), or a numeric day label. */
  date: string | number;
  desktop: number;
  mobile: number;
};

export type CardTrafficProps = {
  data: TrafficDataPoint[];
  bounceRate?: number;
  conversionRate?: number;
};

const formatDate = (value: unknown) => {
  if (typeof value === "number") {
    return `Day ${value}`;
  }
  const date = new Date(String(value));
  return Number.isNaN(date.getTime())
    ? String(value)
    : date.toLocaleDateString("en-US", { month: "short", day: "numeric", timeZone: "UTC" });
};

const chartConfig = {
  mobile: {
    label: "Mobile",
    color: "var(--chart-1)",
  },
  desktop: {
    label: "Desktop",
    color: "var(--chart-2)",
  },
} satisfies ChartConfig;

export function CardTraffic({ data, bounceRate, conversionRate }: CardTrafficProps) {
  const mobile = data.reduce((sum, point) => sum + point.mobile, 0);
  const desktop = data.reduce((sum, point) => sum + point.desktop, 0);
  return (
    <Card
      className="w-full max-w-[600px]"
      style={{
        maxWidth: "600px",
        width: "100%",
      }}
    >
      <CardHeader>
        <CardTitle>Website Traffic</CardTitle>
      </CardHeader>
      <CardContent className="h-[200px] p-0">
        <div style={{ width: "100%", height: "100%" }}>
          <ChartContainer config={chartConfig}>
            <LineChart data={data}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} />
              <XAxis dataKey="date" hide={true} tickFormatter={formatDate} />
              <YAxis hide={true} />
              <ChartTooltip content={<ChartTooltipContent labelFormatter={formatDate} />} />
              <Line
                animationDuration={800}
                dataKey="mobile"
                dot={false}
                stroke="var(--color-mobile)"
                strokeWidth={2}
                type="monotone"
              />
              <Line
                animationBegin={200}
                animationDuration={800}
                dataKey="desktop"
                dot={false}
                stroke="var(--color-desktop)"
                strokeWidth={2}
                type="monotone"
              />
            </LineChart>
          </ChartContainer>
        </div>
      </CardContent>

      <div
        className={cn(
          "-mx-6 -mb-6 grid grid-cols-2 grid-rows-2 border-t-[0.5px] border-t-[oklch(from_var(--border)_l_c_h_/_0.7)]",
          "max-sm:-mx-5 max-sm:-mb-5",
          "max-[400px]:-mx-5 max-[400px]:-mb-5 max-[400px]:grid-cols-1 max-[400px]:grid-rows-auto"
        )}
      >
        <div
          className={cn(
            "flex flex-col gap-2 border-r-[0.5px] border-r-[oklch(from_var(--border)_l_c_h_/_0.7)] border-b-[0.5px] border-b-[oklch(from_var(--border)_l_c_h_/_0.7)] p-5",
            "sm:gap-2 sm:p-4",
            "max-[400px]:border-r-0 max-[400px]:border-b max-[400px]:border-b-[var(--border)] max-[400px]:p-4"
          )}
        >
          <div className="flex items-center justify-between">
            <span className="font-medium text-[var(--muted-foreground)] text-sm leading-5">Mobile</span>
          </div>
          <span className="font-bold text-[32px] text-[var(--foreground)] tabular-nums leading-none max-sm:text-[1.75rem] max-[400px]:text-2xl">
            {mobile.toLocaleString("en-US")}
          </span>
        </div>

        <div
          className={cn(
            "flex flex-col gap-2 border-b-[0.5px] border-b-[oklch(from_var(--border)_l_c_h_/_0.7)] p-5",
            "sm:gap-2 sm:p-4",
            "max-[400px]:border-r-0 max-[400px]:border-b max-[400px]:border-b-[var(--border)] max-[400px]:p-4"
          )}
        >
          <div className="flex items-center justify-between">
            <span className="font-medium text-[var(--muted-foreground)] text-sm leading-5">Desktop</span>
          </div>
          <span className="font-bold text-[32px] text-[var(--foreground)] tabular-nums leading-none max-sm:text-[1.75rem] max-[400px]:text-2xl">
            {desktop.toLocaleString("en-US")}
          </span>
        </div>

        <div
          className={cn(
            "flex flex-col gap-2 border-r-[0.5px] border-r-[oklch(from_var(--border)_l_c_h_/_0.7)] p-5",
            "sm:gap-2 sm:p-4",
            "max-[400px]:border-r-0 max-[400px]:border-b max-[400px]:border-b-[var(--border)] max-[400px]:p-4"
          )}
        >
          <div className="flex items-center justify-between">
            <span className="font-medium text-[var(--muted-foreground)] text-sm leading-5">Bounce Rate</span>
          </div>
          <span className="font-bold text-[32px] text-[var(--foreground)] tabular-nums leading-none max-sm:text-[1.75rem] max-[400px]:text-2xl">
            {bounceRate === undefined ? "Not provided" : `${bounceRate}%`}
          </span>
        </div>

        <div
          className={cn(
            "flex flex-col gap-2 p-5",
            "sm:gap-2 sm:p-4",
            "max-[400px]:border-r-0 max-[400px]:border-b-0 max-[400px]:p-4"
          )}
        >
          <div className="flex items-center justify-between">
            <span className="font-medium text-[var(--muted-foreground)] text-sm leading-5">Conversion</span>
          </div>
          <span className="font-bold text-[32px] text-[var(--foreground)] tabular-nums leading-none max-sm:text-[1.75rem] max-[400px]:text-2xl">
            {conversionRate === undefined ? "Not provided" : `${conversionRate}%`}
          </span>
        </div>
      </div>
    </Card>
  );
}
